function validate([land]) {
  if (!Array.isArray(land) || land.length < 1 || land.length > 300) return 'land needs 1 to 300 rows.';
  const cols = Array.isArray(land[0]) ? land[0].length : 0;
  if (cols < 1 || cols > 300) return 'Each row needs 1 to 300 cells.';
  if (!land.every(row => Array.isArray(row) && row.length === cols)) return 'All rows must have the same length.';
  if (!land.every(row => row.every(v => v === 0 || v === 1))) return 'Each cell is 0 or 1.';
  // Every connected patch of 1s must fill its bounding box exactly.
  const seen = land.map(row => row.map(() => false));
  for (let r = 0; r < land.length; r++) {
    for (let c = 0; c < cols; c++) {
      if (land[r][c] !== 1 || seen[r][c]) continue;
      let cells = 0, top = r, bottom = r, left = c, right = c;
      const stack = [[r, c]];
      seen[r][c] = true;
      while (stack.length) {
        const [y, x] = stack.pop();
        cells++;
        top = Math.min(top, y); bottom = Math.max(bottom, y); left = Math.min(left, x); right = Math.max(right, x);
        for (const [ny, nx] of [[y + 1, x], [y - 1, x], [y, x + 1], [y, x - 1]]) {
          if (ny >= 0 && ny < land.length && nx >= 0 && nx < cols && land[ny][nx] === 1 && !seen[ny][nx]) {
            seen[ny][nx] = true;
            stack.push([ny, nx]);
          }
        }
      }
      if (cells !== (bottom - top + 1) * (right - left + 1)) return 'Each group of farmland must be a filled rectangle, not touching another group along an edge.';
    }
  }
  return null;
}

