function findFarmland(land) {
  const rows = land.length;
  const cols = land[0].length;
  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const groups = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (land[r][c] === 0 || visited[r][c]) {
        continue;
      }
      // Scanning row by row, the first cell met in a group is its top-left corner.
      let bottom = r;
      let right = c;
      const stack = [[r, c]];
      visited[r][c] = true;
      while (stack.length > 0) {
        const [row, col] = stack.pop();
        bottom = Math.max(bottom, row);
        right = Math.max(right, col);
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nextRow = row + dr;
          const nextCol = col + dc;
          if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
            continue;
          }
          if (land[nextRow][nextCol] === 1 && !visited[nextRow][nextCol]) {
            visited[nextRow][nextCol] = true;
            stack.push([nextRow, nextCol]);
          }
        }
      }
      groups.push([r, c, bottom, right]);
    }
  }
  return groups;
}

