function findFarmland(land) {
  // A top-left corner is farmland with no farmland directly above or to its left;
  // from there, walk right and down along the rectangle's edges.
  const result = [];
  for (let i = 0; i < land.length; i++) {
    for (let j = 0; j < land[i].length; j++) {
      if (land[i][j] !== 1) continue;
      if (i > 0 && land[i - 1][j] === 1) continue;
      if (j > 0 && land[i][j - 1] === 1) continue;
      let endRow = i;
      while (endRow + 1 < land.length && land[endRow + 1][j] === 1) endRow++;
      let endCol = j;
      while (endCol + 1 < land[i].length && land[i][endCol + 1] === 1) endCol++;
      result.push([i, j, endRow, endCol]);
    }
  }
  return result;
}

