function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? int(80, 100) : int(1, 6);
  const cols = size === 'large' ? int(80, 100) : int(1, 6);
  const land = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const maxSide = size === 'large' ? 12 : 3;
  const attempts = size === 'large' ? 400 : int(0, 8);
  for (let t = 0; t < attempts; t++) {
    const height = int(1, Math.min(maxSide, rows));
    const width = int(1, Math.min(maxSide, cols));
    const top = int(0, rows - height);
    const left = int(0, cols - width);
    // The rectangle and the cells sharing an edge with it must all be forest (corners may touch).
    let free = true;
    for (let r = top - 1; r <= top + height && free; r++) {
      for (let c = left - 1; c <= left + width && free; c++) {
        const corner = (r === top - 1 || r === top + height) && (c === left - 1 || c === left + width);
        if (corner || r < 0 || r >= rows || c < 0 || c >= cols) continue;
        if (land[r][c] === 1) free = false;
      }
    }
    if (!free) continue;
    for (let r = top; r < top + height; r++) for (let c = left; c < left + width; c++) land[r][c] = 1;
  }
  return [land];
}
